def parse_line(line):
    if ":" not in line:
        return None
    name, _, rest = line.partition(":")
    name = name.strip()
    if not name:
        return None
    marks = []
    if rest.strip():
        for part in rest.split(","):
            part = part.strip()
            if not part.isdigit() or int(part) > 100:
                return None
            marks.append(int(part))
    return (name, marks)


def load(path):
    book = {}
    with open(path, encoding="utf-8") as f:
        for line in f:
            if not line.strip():
                continue
            parsed = parse_line(line)
            if parsed:
                name, marks = parsed
                book[name] = marks
    return book


def average(marks):
    if not marks:
        return None
    return round(sum(marks) / len(marks), 1)


def letter(avg):
    if avg is None:
        return "-"
    for threshold, grade in ((90, "A"), (80, "B"), (70, "C"), (60, "D")):
        if avg >= threshold:
            return grade
    return "F"


def report(book):
    width = len("Name")
    for name in book:
        width = max(width, len(name))
    width += 3
    ranked = []        # (-average, name) pairs, so the highest average sorts first
    no_marks = []
    for name, marks in book.items():
        avg = average(marks)
        if avg is None:
            no_marks.append(name)
        else:
            ranked.append((-avg, name))
    ranked.sort()
    no_marks.sort()
    lines = ["Name".ljust(width) + "Avg".rjust(4) + "  Grade"]
    total = 0
    for negative, name in ranked:
        avg = -negative
        total += avg
        lines.append(name.ljust(width) + f"{avg:.1f}".rjust(4) + "  " + letter(avg))
    for name in no_marks:
        lines.append(name.ljust(width) + "-".rjust(4) + "  " + letter(None))
    overall = f"{total / len(ranked):.1f}" if ranked else "-"
    lines.append(f"{len(book)} students, class average {overall}")
    return "\n".join(lines) + "\n"


def save_report(path, book):
    with open(path, "w", encoding="utf-8") as f:
        f.write(report(book))

