@test("parsing lines")
def _():
    check_eq(parse_line("Ada Lovelace: 90, 85, 77"), ("Ada Lovelace", [90, 85, 77]))
    check_eq(parse_line("  Linus :  "), ("Linus", []))
    check_eq(parse_line("Grace:100,0"), ("Grace", [100, 0]))
    check_eq(parse_line("no colon here"), None)
    check_eq(parse_line(": 90"), None)
    check_eq(parse_line("Ada: 90, x"), None)
    check_eq(parse_line("Ada: 101"), None)
    check_eq(parse_line("Ada: 90,,80"), None)

@test("loading a file")
def _():
    with open("marks.txt", "w", encoding="utf-8") as f:
        f.write("Ada Lovelace: 90, 85, 77\n\nbroken line\nGrace Hopper: 95, 89\nLinus:\nAda Lovelace: 80, 88\n")
    check_eq(load("marks.txt"), {"Ada Lovelace": [80, 88], "Grace Hopper": [95, 89], "Linus": []})

@test("averages and letters")
def _():
    check_eq(average([90, 85, 77]), 84.0)
    check_eq(average([1, 2]), 1.5)
    check_eq(average([]), None)
    check_eq([letter(a) for a in (95, 90, 89.9, 70, 60, 59.9, None)], ["A", "A", "B", "C", "D", "F", "-"])

@test("the report")
def _():
    book = {"Ada Lovelace": [80, 88], "Grace Hopper": [95, 89], "Linus": []}
    check_eq(report(book), "Name            Avg  Grade\nGrace Hopper   92.0  A\nAda Lovelace   84.0  B\nLinus             -  -\n3 students, class average 88.0\n")
    check_eq(report({"Bo": [50], "Al": [50]}), "Name    Avg  Grade\nAl     50.0  F\nBo     50.0  F\n2 students, class average 50.0\n")
    check_eq(report({}), "Name    Avg  Grade\n0 students, class average -\n")

@test("saving")
def _():
    save_report("report.txt", {"Ada": [100]})
    with open("report.txt", encoding="utf-8") as f:
        check_eq(f.read(), "Name    Avg  Grade\nAda    100.0  A\n1 students, class average 100.0\n")

